arguments.content:
:root {
  --bg-color: #0a0a0a;
  --surface-color: #141414;
  --surface-hover: #1f1f1f;
  --border-color: #262626;
  --text-primary: #ffffff;
  --text-secondary: #a3a3a3;
  --accent-color: #3b82f6;
  --accent-hover: #2563eb;

  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;

  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 2rem;
  --space-lg: 4rem;
  --space-xl: 8rem;

  --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  --radius: 0; /* Kinetic Brutalism influence, sharp corners */
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg-color);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

.container {
  width: 100%;
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 5%;
}

h1, h2, h3, h4, h5, h6 {
  font-weight: 500;
  line-height: 1.1;
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.5rem, 5vw, 4.5rem); }
h2 { font-size: clamp(2rem, 4vw, 3.5rem); margin-bottom: var(--space-sm); }
h3 { font-size: clamp(1.5rem, 2.5vw, 2rem); }
p { font-size: 1.125rem; color: var(--text-secondary); }

a {
  color: inherit;
  text-decoration: none;
  transition: var(--transition);
}

ul {
  list-style: none;
}

button {
  font-family: inherit;
  border: none;
  background: none;
  cursor: pointer;
  color: inherit;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 1rem 2rem;
  font-weight: 500;
  font-size: 1rem;
  transition: var(--transition);
  text-align: center;
}

.btn-primary {
  background-color: var(--text-primary);
  color: var(--bg-color);
}
.btn-primary:hover, .btn-primary:focus-visible {
  background-color: var(--text-secondary);
  outline: 2px solid var(--text-primary);
  outline-offset: 2px;
}

.btn-outline {
  border: 1px solid var(--text-primary);
  color: var(--text-primary);
}
.btn-outline:hover, .btn-outline:focus-visible {
  background-color: var(--text-primary);
  color: var(--bg-color);
}

.btn-accent {
  background-color: var(--accent-color);
  color: #fff;
}
.btn-accent:hover {
  background-color: var(--accent-hover);
}

/* Navbar */
.navbar {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  padding: 1.5rem 5%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  z-index: 100;
  background-color: rgba(10, 10, 10, 0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
  transition: transform 0.3s ease;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.03em;
}

.nav-links {
  display: flex;
  gap: 2rem;
}

.nav-links a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-secondary);
}
.nav-links a:hover {
  color: var(--text-primary);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.lang-selector {
  position: relative;
}
#lang-btn {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.9375rem;
  color: var(--text-secondary);
}
#lang-btn:hover {
  color: var(--text-primary);
}
#lang-btn svg {
  width: 16px;
  height: 16px;
  fill: currentColor;
  transition: transform 0.3s ease;
}
.lang-selector.active #lang-btn svg {
  transform: rotate(180deg);
}
.lang-dropdown {
  position: absolute;
  top: 100%;
  right: 0;
  margin-top: 1rem;
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  min-width: 160px;
  opacity: 0;
  visibility: hidden;
  transform: translateY(-10px);
  transition: var(--transition);
}
.lang-selector.active .lang-dropdown {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.lang-dropdown a {
  display: block;
  padding: 0.75rem 1rem;
  font-size: 0.875rem;
  border-bottom: 1px solid var(--border-color);
}
.lang-dropdown a:last-child {
  border-bottom: none;
}
.lang-dropdown a:hover {
  background-color: var(--surface-hover);
  color: var(--accent-color);
}

.mobile-menu-toggle {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
}
.mobile-menu-toggle svg {
  width: 24px;
  height: 24px;
}

/* Sections */
section {
  padding: var(--space-xl) 0;
}

.section-header {
  margin-bottom: var(--space-lg);
  max-width: 800px;
}
.section-header h2 {
  margin-bottom: var(--space-xs);
}
.section-header p {
  font-size: 1.25rem;
}

/* Hero Carousel */
.hero-carousel {
  position: relative;
  height: 100vh;
  min-height: 600px;
  padding: 0;
  overflow: hidden;
}

.hero-track {
  display: flex;
  height: 100%;
  transition: transform 0.6s cubic-bezier(0.25, 1, 0.5, 1);
}

.hero-slide {
  flex: 0 0 100%;
  height: 100%;
  position: relative;
  display: flex;
  align-items: center;
  padding: 0 5%;
  background-size: cover;
  background-position: center;
}

.hero-slide::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to right, rgba(10,10,10,0.9) 0%, rgba(10,10,10,0.4) 100%);
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 700px;
  opacity: 0;
  transform: translateY(20px);
  transition: all 0.6s ease 0.3s;
}

.hero-slide.active .hero-content {
  opacity: 1;
  transform: translateY(0);
}

.hero-content h2 {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  margin-bottom: var(--space-sm);
}
.hero-content p {
  font-size: clamp(1.125rem, 2vw, 1.5rem);
  margin-bottom: var(--space-md);
  color: var(--text-primary);
}

.hero-controls {
  position: absolute;
  bottom: 3rem;
  left: 5%;
  z-index: 10;
  display: flex;
  align-items: center;
  gap: 2rem;
}

.hero-nav-btns {
  display: flex;
  gap: 1rem;
}
.hero-nav-btns button {
  width: 48px;
  height: 48px;
  border: 1px solid rgba(255,255,255,0.3);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  color: white;
}
.hero-nav-btns button:hover {
  background: white;
  color: black;
}
.hero-nav-btns svg {
  width: 20px;
  height: 20px;
  fill: currentColor;
}

.hero-indicators {
  display: flex;
  gap: 0.5rem;
}
.hero-indicator {
  width: 40px;
  height: 2px;
  background-color: rgba(255,255,255,0.3);
  transition: var(--transition);
}
.hero-indicator.active {
  background-color: var(--text-primary);
}

/* Global Studios */
.region-tabs {
  display: flex;
  gap: 2rem;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: var(--space-lg);
  overflow-x: auto;
  scrollbar-width: none; /* Firefox */
}
.region-tabs::-webkit-scrollbar {
  display: none; /* Safari and Chrome */
}

.tab-btn {
  padding: 1rem 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--text-secondary);
  position: relative;
  white-space: nowrap;
}
.tab-btn:hover {
  color: var(--text-primary);
}
.tab-btn.active {
  color: var(--text-primary);
}
.tab-btn.active::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  width: 100%;
  height: 2px;
  background-color: var(--accent-color);
}

.team-carousel-container {
  position: relative;
}

.team-track {
  display: flex;
  gap: 2rem;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding-bottom: 1rem;
}
.team-track::-webkit-scrollbar {
  display: none;
}

.team-card {
  flex: 0 0 350px;
  scroll-snap-align: start;
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
}
.team-img {
  width: 100%;
  height: 250px;
  background-color: var(--border-color);
  background-size: cover;
  background-position: center;
}
.team-content {
  padding: 2rem;
  flex: 1;
  display: flex;
  flex-direction: column;
}
.team-quote {
  font-size: 1rem;
  font-style: italic;
  margin-bottom: 1.5rem;
  flex: 1;
}
.team-meta h4 {
  font-size: 1.25rem;
  margin-bottom: 0.25rem;
}
.team-meta p {
  font-size: 0.875rem;
  color: var(--accent-color);
  margin-bottom: 1.5rem;
}
.team-link {
  font-size: 0.875rem;
  font-weight: 500;
  text-decoration: underline;
  text-underline-offset: 4px;
}
.team-link:hover {
  color: var(--accent-color);
}

/* Client Work */
.work-scroller {
  width: 100%;
  overflow: hidden;
  padding-left: 5%;
}
.work-track {
  display: flex;
  gap: 2rem;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  padding-right: 5%;
  padding-bottom: 2rem;
  scrollbar-width: none;
}
.work-track::-webkit-scrollbar {
  display: none;
}

.work-card {
  flex: 0 0 calc(80vw - 2rem);
  max-width: 600px;
  scroll-snap-align: start;
  position: relative;
  group: true;
}

.work-img-wrapper {
  width: 100%;
  aspect-ratio: 16/9;
  background-color: var(--surface-color);
  overflow: hidden;
  margin-bottom: 1.5rem;
}
.work-img {
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
  transition: transform 0.7s ease;
}
.work-card:hover .work-img {
  transform: scale(1.05);
}

.work-info h3 {
  font-size: 1.5rem;
  margin-bottom: 0.5rem;
}
.work-info p {
  font-size: 1rem;
}

/* CTA Banner */
.cta-banner {
  background-color: var(--accent-color);
  color: #fff;
  padding: var(--space-xl) 0;
  text-align: center;
}
.cta-banner h2 {
  font-size: clamp(2.5rem, 5vw, 4rem);
}
.cta-banner p {
  color: rgba(255,255,255,0.9);
  margin: 0 auto var(--space-md);
  font-size: 1.25rem;
}
.cta-banner .btn {
  background-color: var(--bg-color);
  color: var(--text-primary);
}
.cta-banner .btn:hover {
  background-color: var(--text-primary);
  color: var(--bg-color);
}

/* How We Work */
.how-we-work {
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
  background-color: var(--surface-color);
}
.how-we-work .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}
.how-we-work p {
  font-size: 1.25rem;
  margin-bottom: 2rem;
}

/* Latest Insights */
.insights-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 2rem;
}
.insight-card {
  display: flex;
  flex-direction: column;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 1.5rem;
  transition: var(--transition);
}
.insight-card:hover {
  border-color: var(--text-primary);
}
.insight-type {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--accent-color);
  margin-bottom: 0.5rem;
}
.insight-title {
  font-size: 1.25rem;
  font-weight: 500;
  margin-bottom: 1rem;
}
.insight-cta {
  margin-top: auto;
  font-size: 0.875rem;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}
.insight-cta:hover {
  color: var(--accent-color);
}
.insight-cta svg {
  width: 16px;
  height: 16px;
  fill: currentColor;
}

/* Principles */
.principles {
  background-color: var(--bg-color);
}
.principles-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 3rem;
  margin-top: 3rem;
}
.principle-item {
  border-left: 2px solid var(--border-color);
  padding-left: 1.5rem;
}
.principle-item h3 {
  font-size: 1.25rem;
  margin-bottom: 1rem;
}
.principle-item p {
  font-size: 1rem;
}

/* Footer */
.footer {
  background-color: var(--surface-color);
  padding: 4rem 0 2rem;
  border-top: 1px solid var(--border-color);
}
.footer-top {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  margin-bottom: 4rem;
}
.footer-cta-block h3 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
}
.footer-cta-block p {
  margin-bottom: 1.5rem;
}
.footer-bottom {
  display: flex;
  flex-direction: column;
  gap: 2rem;
  border-top: 1px solid var(--border-color);
  padding-top: 2rem;
}
.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}
.footer-links a {
  font-size: 0.875rem;
  color: var(--text-secondary);
}
.footer-links a:hover {
  color: var(--text-primary);
}
.footer-legal {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem;
  font-size: 0.75rem;
  color: var(--text-secondary);
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 2rem;
  left: 5%;
  right: 5%;
  max-width: 600px;
  background-color: var(--surface-color);
  border: 1px solid var(--border-color);
  padding: 1.5rem;
  z-index: 1000;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  box-shadow: 0 20px 40px rgba(0,0,0,0.5);
  transform: translateY(150%);
  transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}
.cookie-banner.show {
  transform: translateY(0);
}
.cookie-banner p {
  font-size: 0.875rem;
}
.cookie-actions {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}
.cookie-actions button {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
  border: 1px solid var(--border-color);
  transition: var(--transition);
}
.cookie-actions button.primary {
  background-color: var(--text-primary);
  color: var(--bg-color);
  border-color: var(--text-primary);
}
.cookie-actions button:hover {
  background-color: var(--text-secondary);
  color: var(--bg-color);
}

/* Responsive */
@media (max-width: 1024px) {
  .how-we-work .container {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
  .footer-top {
    grid-template-columns: 1fr;
    gap: 3rem;
  }
}

@media (max-width: 768px) {
  .nav-links, .lang-selector {
    display: none;
  }
  .mobile-menu-toggle {
    display: block;
  }

  .hero-controls {
    flex-direction: column;
    align-items: flex-start;
    gap: 1rem;
  }

  .work-card {
    flex: 0 0 calc(90vw - 2rem);
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // Lang Selector Toggle
  const langBtn = document.getElementById('lang-btn');
  const langSelector = langBtn?.closest('.lang-selector');

  if (langBtn && langSelector) {
    langBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      langSelector.classList.toggle('active');
    });

    document.addEventListener('click', () => {
      langSelector.classList.remove('active');
    });
  }

  // Hero Carousel Logic
  const track = document.getElementById('hero-track');
  const slides = track ? Array.from(track.children) : [];
  const prevBtn = document.querySelector('.hero-nav-btns .prev-btn');
  const nextBtn = document.querySelector('.hero-nav-btns .next-btn');
  const indicators = document.querySelectorAll('.hero-indicator');

  if (track && slides.length > 0) {
    let currentSlide = 0;
    const slideCount = slides.length;
    let autoPlayInterval;

    function goToSlide(index) {
      if (index < 0) index = slideCount - 1;
      if (index >= slideCount) index = 0;

      currentSlide = index;
      track.style.transform = `translateX(-${currentSlide * 100}%)`;

      slides.forEach((slide, i) => {
        slide.classList.toggle('active', i === currentSlide);
      });

      indicators.forEach((indicator, i) => {
        indicator.classList.toggle('active', i === currentSlide);
      });
    }

    function nextSlide() {
      goToSlide(currentSlide + 1);
    }

    function prevSlide() {
      goToSlide(currentSlide - 1);
    }

    if (prevBtn) prevBtn.addEventListener('click', () => {
      prevSlide();
      resetAutoPlay();
    });

    if (nextBtn) nextBtn.addEventListener('click', () => {
      nextSlide();
      resetAutoPlay();
    });

    indicators.forEach((indicator, i) => {
      indicator.addEventListener('click', () => {
        goToSlide(i);
        resetAutoPlay();
      });
    });

    function startAutoPlay() {
      autoPlayInterval = setInterval(nextSlide, 5000);
    }

    function resetAutoPlay() {
      clearInterval(autoPlayInterval);
      startAutoPlay();
    }

    // Initialize
    goToSlide(0);
    startAutoPlay();
  }

  // Team Carousel Logic
  const teamData = [
    { name: "Denice Alvarez", title: "Office Manager", office: "New York", region: "north-america", quote: "As the Office Manager, I engage with teams from every discipline, and have learned so much through my day-to-day interactions with my fellow leapers." },
    { name: "Marco Bellini", title: "Design Director", office: "San Francisco", region: "north-america", quote: "Every day we are delighted by the immense beauty that nature holds. When engaged in the act of creation, it is our responsibility to channel that delight into the things we make." },
    { name: "Priya Mehta", title: "Studio Head", office: "Bangalore", region: "asia", quote: "We bring your brand vision to life, with transformative ideas and impactful marketing campaigns fueled by creativity and enthusiasm." },
    { name: "Thierry Lam", title: "Design Lead", office: "Singapore", region: "asia", quote: "Good design is multifaceted. It impacts functionality, aesthetics, strategy, environment, business and so much more. Great design is seamless." },
    { name: "Gavin Hartley", title: "Managing Director", office: "London", region: "europe", quote: "It's my job to make sure we innovate and push the boundaries when collaborating with brands to create inspiring customer experiences that deliver great business results." },
    { name: "Francesca Terzi", title: "Design Director", office: "Munich", region: "europe", quote: "At Leap Studio, I am constantly amazed by the talent I am surrounded with. We love to dream big and bring those dreams to life." },
    { name: "Jacintha Soo Ho", title: "Senior Manager, CX Transformation", office: "Melbourne", region: "oceania", quote: "I love helping clients see beyond their assumptions and showing them opportunities they haven't thought of before." }
  ];

  const teamTrack = document.getElementById('team-track');
  const regionTabs = document.querySelectorAll('.tab-btn');

  function renderTeam(region) {
    if (!teamTrack) return;

    teamTrack.innerHTML = '';
    const filteredTeam = teamData.filter(member => member.region === region);

    filteredTeam.forEach(member => {
      const card = document.createElement('div');
      card.className = 'team-card';
      // Muted placeholder background using Unsplash source API matching the professional aesthetic
      card.innerHTML = `
        <div class="team-img" style="background-image: url('https://images.unsplash.com/photo-1573164713988-8665fc963095?q=80&w=800&auto=format&fit=crop')"></div>
        <div class="team-content">
          <p class="team-quote">"${member.quote}"</p>
          <div class="team-meta">
            <h4>${member.name}</h4>
            <p>${member.title}</p>
            <a href="#" class="team-link">Contact Leap Studio ${member.office}</a>
          </div>
        </div>
      `;
      teamTrack.appendChild(card);
    });

    // Reset scroll
    teamTrack.scrollLeft = 0;
  }

  if (regionTabs.length > 0) {
    regionTabs.forEach(tab => {
      tab.addEventListener('click', () => {
        // Update active tab
        regionTabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');

        // Render team for selected region
        const region = tab.dataset.region;
        renderTeam(region);
      });
    });

    // Initial render
    const initialRegion = document.querySelector('.tab-btn.active')?.dataset.region || 'north-america';
    renderTeam(initialRegion);
  }

  // Cookie Banner Logic
  const cookieBanner = document.getElementById('cookie-banner');
  if (cookieBanner) {
    // Show banner after short delay
    setTimeout(() => {
      cookieBanner.classList.add('show');
    }, 1500);

    const hideBanner = () => {
      cookieBanner.classList.remove('show');
    };

    const cookieBtns = cookieBanner.querySelectorAll('button');
    cookieBtns.forEach(btn => {
      btn.addEventListener('click', hideBanner);
    });
  }
});
